update content_bodies set title = 'ナガシマジャンボ海水プール「ジャパーーーーン」(桑名市)｜観光三重｜三重県の観光・旅行情報', description = 'ナガシマジャンボ海水プールの人気アトラクション「ジャパ――――ン」の衝撃を体験してきました！
高さ約18ｍから大量の水が流れ落ちる、大人気の「ジャパーーーーーン」。
タワー最高部にある約3トンの巨大バケツと、他の2つの巨大バケツと合わせて総重量6トンもの水が一気に流れ落ちます！

2018年6月30日撮影
※許可を得て撮影しています

ナガシマジャンボ海水プールの詳しい取材レポートはこちら↓
『世界最大級の「ナガシマ　ジャンボ海水プール」オープン！日本初上陸の「超激流プール」に大興奮！』
https://www.kankomie.or.jp/report/detail_229.html

【ナガシマスパーランド取材レポート】
ナガシマスパーランドを徹底解説！人気の絶叫アトラクションや合わせて行きたい周辺人気施設をご紹介します！
https://www.kankomie.or.jp/report/detail_554.html

