三重県桑名市にある「ナガシマリゾート」には、「絶叫マシンの聖地」として知られる人気遊園地「ナガシマスパーランド」をはじめ、「ジャンボ海水プール」、イルミネーションで有名な「なばなの里」、アウトレットパーク「ジャズドリーム長島」、子ども大好き「名古屋アンパンマン子どもミュージアム&パーク」などの人気スポットが盛りだくさん！
