update content_bodies set title = '円座・佐八かんこ踊り', description = 'かんこ踊りは白馬の尾で作ったじゃぐまをかぶり、太鼓を叩いて篝火の周りを輪になって踊るお盆の行事(県指定無形民俗文化財)です。胸に抱えた太鼓をたたきながら松明の周りを舞う姿に魅せられます。

詳細については、HP観光三重をごらんください。
https://www.kankomie.or.jp' where id = 'KZ38mMnTyzODgOAv694Bg';
update content_bodies set title = 'Enza - Sahachi Kanko Dance', description = 'The Kanko Dance is a Bon Festival event where participants wear a jaguma made from the tail of a white horse, beat drums, and dance in a circle around a bonfire (designated as an intangible folk cultural asset by the prefecture). The sight of dancers performing around the torches while beating the drums they hold in their arms is captivating.

For more details, please visit the HP Tourism Mie.
https://www.kankomie.or.jp' where id = 'rXcU65XEaOopKIZZN23Kr';
update content_bodies set title = '植木神社祇園祭', description = '宵宮祭と遷幸祭からなる祭りで、勇壮に練る神輿と江戸時代から大切に使われている豪華な楼車が町内を巡行する。神輿を傾けながら回る「クネリ」や祇園花の行列が中心となる華やかな祭りは、多くの見物客が訪れます。

詳細については、ＨP「観光三重」をごらんください。
https://www.kankomie.or.jp' where id = 'KmuDDCMPDVIAGBhfOb3ua';
update content_bodies set title = 'Ueki Shrine Gion Festival', description = 'A festival consisting of the Yoimiya Festival and the Senkou Festival, featuring a magnificent procession of portable shrines and luxurious floats that have been cherished since the Edo period. The vibrant festival, centered around the ''Kuneri'' where the portable shrines are tilted and the Gion flower parade, attracts many spectators.

For more details, please visit the HP ''Tourism Mie''.
https://www.kankomie.or.jp' where id = 'reDlgelnoumugHJk1nVov';
update content_bodies set title = 'ざるやぶり神事', description = '約450年の伝統を受け継ぐ祭り。ふんどし姿の青年たちが神前に供えたお饌米の入っていた直径約90㎝のざるを奪い合います。からだをぶつけ合いもみ合いながら、ざるをやぶる姿は迫力満点です。

詳細については、HＰ「観光三重」をごらんください。
https://www.kankomie.or.jp' where id = 'T4lOKqnbn2eqJT2bfUv6q';
update content_bodies set title = 'Zaru Yaburi Festival', description = 'A festival that has inherited a tradition of about 450 years. Young men in fundoshi compete to snatch a zaru, a basket with a diameter of about 90 cm that contains rice offerings presented before the deity. The sight of them colliding and grappling to tear the zaru apart is truly spectacular.

For more details, please visit the HP ''Kankou Mie''.
https://www.kankomie.or.jp' where id = 'NN72PDEHkrXoPMFZ5dCsL';
update content_bodies set title = 'ミキモト真珠島', description = '明治26年、御木本幸吉が世界で初めて真珠の養殖に成功した島。夏休みは、真珠のティアラをつけて、お手持ちのｶﾒﾗで記念撮影ができる「真珠のティアラで華麗に変身」や淡水真珠を使った「ストラップ工房」や「万華鏡工房」など開催します。

詳細については、ＨＰ「観光三重」をご覧ください。
https://www.kankomie.or.jp' where id = 'ZPubLahPG5rJld4FbP8b5';
update content_bodies set title = 'Mikimoto Pearl Island', description = 'In 1893, Kokichi Mikimoto succeeded in the world''s first pearl cultivation on this island. During the summer vacation, you can participate in events such as ''Transform into Elegance with a Pearl Tiara'' where you can wear a pearl tiara and take commemorative photos with your own camera, as well as workshops like ''Strap Workshop'' and ''Kaleidoscope Workshop'' using freshwater pearls.

For more details, please visit the HP ''Tourism Mie''.
https://www.kankomie.or.jp' where id = 'FJtkZjQpnsWit1JYMEOEf';
update content_bodies set title = '伊勢・安土桃山文化村', description = '安土城を丸々使ったお化け屋敷はここだけ!業火の責め苦に喘ぎ、逃げ惑う阿鼻叫喚の地獄絵図です。来場者には、指令が下され、怨魂蠢く安土城からあなたは無事脱出できるかな?

詳細についてはＨＰ「観光三重」をごらんください。
https://www.kankomie.or.jp' where id = 'KVdapl9YA6ctyR3bZAdKY';
update content_bodies set title = 'Ise Azuchi Momoyama Cultural Village', description = 'The haunted house that fully utilizes Azuchi Castle is unique to this place! It is a hellish scene of agony and despair, where people are tormented by raging flames and flee in panic. Visitors will receive a command, and will you be able to escape safely from the haunted Azuchi Castle where vengeful spirits lurk?

For more details, please visit the website ''Kankou Mie''.
https://www.kankomie.or.jp' where id = '1_5fzkf7G9qZWa8_zNhVb';
update content_bodies set title = '熊野大花火大会', description = '約10000発もの大迫力の花火が打ち上がります。フィナーレを飾る鬼ヶ城大仕掛けは、鬼ヶ城の岩場や洞窟から仕掛花火が打ち上がり、爆発音が岩場で共鳴する大迫力の演出に魅せられます。

