https://www.kankomie.or.jp' where id = 'gePgbzL-stBmt_FzspZ1x';
update content_bodies set title = 'Kumano Grand Fireworks Festival', description = 'About 10,000 spectacular fireworks will be launched. The grand finale features a large-scale display from the cliffs and caves of Onigajo, where the fireworks are launched, creating a powerful performance as the explosive sounds resonate off the rocks.

For more details, please visit the HP ''Tourism Mie''.
https://www.kankomie.or.jp' where id = '7V9CKluMnMBp8Nz3FatZe';
update content_bodies set title = '松阪祇園まつり', description = '宵宮の午後、松阪・御厨・八雲3つの神社から繰り出す「三社みこし」。揃いの法被姿で1000人もの老若男女が「チョーサヤ」の掛け声と供にまちなかを勇壮に練り歩きます。本日には「松阪しょんがい音頭と踊り」などの踊りやステージイベントなどが披露されます。

