update content_bodies set title = '史跡斎宮跡', description = '天皇に代わり伊勢神宮の天照大神に支えた斎王が暮らした斎宮。その史跡周辺には、平安時代の斎宮寮庁の建物三棟を復元した「さいくう平安の杜」など、幻の宮とされた斎宮の世界にスポットが点在します。

詳細については、ＨP観光三重をごらんください。
https://www.kankomie.or.jp' where id = 'iRPOTDUrRN2S2EKpCFgyy';
update content_bodies set title = 'Historical Site of Saiku', description = 'The Saiku where the priestess lived, supported by the goddess Amaterasu of Ise Jingu on behalf of the Emperor. Around this historical site, there are spots scattered throughout the world of Saiku, which was considered a phantom palace, including ''Saiku Heian no Mori,'' which has restored three buildings of the Saiku Ryocho from the Heian period.

For more details, please visit the HP of Kankou Mie.
https://www.kankomie.or.jp' where id = 'nr8s1XOx6Z1xlb3cUinD9';
update content_bodies set title = '世界遺産 巡礼路「熊野古道伊勢路」 ～映像シリーズ１', description = '古より日本人は万物に神が宿ると信じ、自然を神と崇めてきた…。

太陽の神、天照大御神がお祀りされている伊勢神宮。
ここで旅の無事を祈り、熊野への旅を始めます。
伊勢路は、伊勢から熊野までおよそ170キロ。
様々な顔、様々な表情をした峠をいくつも越えて行きます。
－－－－－－－－－－－－－－－－－－－－－－－－－－－
熊野古道とは、日本の各地から和歌山県にある熊野三山（熊野速玉大社、熊野那智大社、熊野本宮大社）を目指した巡礼者が歩いた古道のこと。
伊勢神宮と熊野三山という日本の二大聖地をむすぶ世界遺産である巡礼の道「熊野古道伊勢路」の歴史と魅力を紹介します。
●熊野古道伊勢路　公式サイト
　→　http://www.kodo.pref.mie.lg.jp/
●初めての熊野古道　～伊勢路を歩く
　→　https://www.kankomie.or.jp/special/kumanokodo/
●日本の2大聖地をむすぶ熊野古道伊勢路の魅力 Part.1
　→　https://www.japanhoppers.com/ja/features/culture/375/
●日本の2大聖地をむすぶ熊野古道伊勢路の魅力 Part.2
　→　https://www.japanhoppers.com/ja/features/culture/376/' where id = '5q24VC5cE8tRoLVJ94Ct-';
update content_bodies set title = 'World Heritage Pilgrimage Route ''Kumano Kodo Iseji'' - Video Series 1', description = 'Since ancient times, the Japanese have believed that gods reside in all things and have revered nature as divine...

Ise Jingu, where the sun goddess Amaterasu Omikami is enshrined.
Here, we pray for a safe journey and begin our pilgrimage to Kumano.
The Iseji route stretches approximately 170 kilometers from Ise to Kumano.
We will cross many mountain passes, each with its own unique face and expression.
－－－－－－－－－－－－－－－－－－－－－－－－－－－
The Kumano Kodo refers to the ancient paths walked by pilgrims aiming for the three Kumano shrines (Kumano Hayatama Taisha, Kumano Nachi Taisha, and Kumano Hongu Taisha) located in Wakayama Prefecture from various parts of Japan.
We will introduce the history and charm of the World Heritage pilgrimage route ''Kumano Kodo Iseji,'' which connects the two major sacred sites of Japan, Ise Jingu and the Kumano Sanzan.
● Official Website of Kumano Kodo Iseji
　→　http://www.kodo.pref.mie.lg.jp/
● First Time on Kumano Kodo - Walking the Iseji
　→　https://www.kankomie.or.jp/special/kumanokodo/
● The Charm of Kumano Kodo Iseji Connecting Japan''s Two Major Sacred Sites Part.1
　→　https://www.japanhoppers.com/ja/features/culture/375/
● The Charm of Kumano Kodo Iseji Connecting Japan''s Two Major Sacred Sites Part.2
　→　https://www.japanhoppers.com/ja/features/culture/376/' where id = 'LHaWiJNXfyilZkRbjwnsF';
update content_bodies set title = '世界遺産 巡礼路「熊野古道伊勢路」 ～映像シリーズ２', description = '巡礼の道には、祖先を敬い、自然を大切に守る人々の暮らしがある…。

手をあわせて旅の無事を願ってくれる、年を召した里の人。
木の精霊と話して、舟を作る人。
「耕して天に至る」と称される棚田を耕す人。
自然と、神々と、共存する人々が暮らします。
－－－－－－－－－－－－－－－－－－－－－－－－－－－－
熊野古道とは、日本の各地から和歌山県にある熊野三山（熊野速玉大社、熊野那智大社、熊野本宮大社）を目指した巡礼者が歩いた古道のこと。
伊勢神宮と熊野三山という日本の二大聖地をむすぶ世界遺産である巡礼の道「熊野古道伊勢路」の歴史と魅力を紹介します。
●熊野古道伊勢路　公式サイト
　→　http://www.kodo.pref.mie.lg.jp/
●初めての熊野古道　～伊勢路を歩く
　→　https://www.kankomie.or.jp/special/kumanokodo/
●日本の2大聖地をむすぶ熊野古道伊勢路の魅力 Part.1
　→　https://www.japanhoppers.com/ja/features/culture/375/
●日本の2大聖地をむすぶ熊野古道伊勢路の魅力 Part.2
　→　https://www.japanhoppers.com/ja/features/culture/376/' where id = '4pdxM24xH6uni2MXv3nGy';
update content_bodies set title = 'World Heritage Pilgrimage Route ''Kumano Kodo Iseji'' - Video Series 2', description = 'On the pilgrimage path, there are lives of people who respect their ancestors and cherish nature...

An elderly villager who prays for the safety of travelers with hands together.
A person who talks to the spirits of trees and builds boats.
A person who cultivates terraced rice fields, known as ''plowing to the heavens.''
People live in harmony with nature and the gods.
－－－－－－－－－－－－－－－－－－－－－－－－－－－－
The Kumano Kodo is an ancient path walked by pilgrims aiming for the Kumano Sanzan (Kumano Hayatama Taisha, Kumano Nachi Taisha, Kumano Hongu Taisha) in Wakayama Prefecture from various parts of Japan.
This is an introduction to the history and charm of the World Heritage pilgrimage route ''Kumano Kodo Iseji,'' which connects the two major sacred sites of Japan, Ise Jingu and Kumano Sanzan.
● Kumano Kodo Iseji Official Website
　→　http://www.kodo.pref.mie.lg.jp/
● First Time on Kumano Kodo - Walking Iseji
　→　https://www.kankomie.or.jp/special/kumanokodo/
● The Charm of Kumano Kodo Iseji Connecting Japan''s Two Major Sacred Sites Part.1
　→　https://www.japanhoppers.com/ja/features/culture/375/
● The Charm of Kumano Kodo Iseji Connecting Japan''s Two Major Sacred Sites Part.2
　→　https://www.japanhoppers.com/ja/features/culture/376/' where id = '9q55NOGM-q7FCRUSF7mmA';
update content_bodies set title = '伊賀のかたやき　鎌田製菓さん', description = '伊賀名物の豆腐田楽「わかや」さんと、かたやきのお店「鎌田製菓」さんに行ってきました　取材レポート記事はこちら　https://www.kankomie.or.jp/report/detail_179.html' where id = 'yKYE8emzhA-AX8Z8dYUHy';
