update content_bodies set title = '伊勢神宮から車で15分！伊勢夫婦岩ふれあい水族館 伊勢シーパラダイスで海獣たちと交流　その２', description = '世界最大の旅行サイト「トリップアドバイザー」で、過去に「国内人気の水族館部門　第５位」を獲得した「伊勢夫婦岩ふれあい水族館 伊勢シーパラダイス」へ行ってきました。詳しくは　https://www.kankomie.or.jp/report/detail_181.html' where id = 'EARkGSO_nfjEcfg3s5c2Y';
update content_bodies set title = '15 minutes by car from Ise Jingu! Interact with marine animals at Ise Sea Paradise, the Ise Couple Rocks Interaction Aquarium Part 2', description = 'I visited the ''Ise Couple Rocks Interaction Aquarium, Ise Sea Paradise,'' which previously ranked 5th in the ''Domestic Popular Aquariums'' category on the world''s largest travel site, TripAdvisor. For more details, visit https://www.kankomie.or.jp/report/detail_181.html' where id = 'VueC0kB39MyPnb37gVHTU';
