update content_bodies set title = '廣澤徳三郎工房で伊賀組紐作り体験', description = '伊賀市の体験メニューで有名な「伊賀組紐（いがくみひも）作り」と伊賀焼陶芸体験をしてきました!今回はその２つをレポートします。2016年津クイーン　角谷 奈津実さんがモデルです。レポート詳細はこちら　https://www.kankomie.or.jp/report/detail_178.html' where id = 'S1S-XhgulU52RNtVRZ0M2';
update content_bodies set title = 'Experience Iga Kumihimo Making at Hirozawa Tokusaburo Workshop', description = 'I had the opportunity to try the famous ''Iga Kumihimo'' making and Iga pottery experience in Iga City! This time, I will report on these two activities. The model is Natsumi Kakutani, Miss Tsu Queen 2016. For more details, visit here: https://www.kankomie.or.jp/report/detail_178.html' where id = 'Q0TUAl2ZogdJKkEHv-Exd';
update content_bodies set title = 'かわいいイルカたちにも会える「鳥羽湾めぐりとイルカ島」その２', description = '豪華遊覧船で鳥羽湾を優雅に遊覧！ かわいいイルカたちにも会える「鳥羽湾めぐりとイルカ島」　観光三重HPに取材レポートを掲載しています。ぜひご覧ください。https://www.kankomie.or.jp/report/detail_176.html' where id = 'yw7XvRCAYdf_zA39lqnYI';
