update content_bodies set title = '四日市コンビナート夜景クルーズ', description = '日本を代表する工場夜景の聖地・四日市。ベテランのガイドさんが同乗し、宝石のような工場夜景はもちろん、遠くは中部国際空港セントレアの夜景まで、特に、第一コンビナートの幻想的な夜景は息を飲む美しさです。' where id = '3Jlf_FXrZ5wbC6H1_vnBW';
update content_bodies set title = 'Yokkaichi Industrial Complex Night View Cruise', description = 'Yokkaichi, a sacred place for Japan''s representative factory night views. A veteran guide will accompany you, showcasing not only the jewel-like factory night views but also the distant night view of Chubu Centrair International Airport. In particular, the fantastical night view of the First Complex is breathtakingly beautiful.' where id = 'JOjshwXym2iuzV5FXosVw';
update content_bodies set title = '伊賀流忍者博物館', description = '伊賀上野城や俳聖殿など名所が多い上野公園内にある忍者博物館です。忍者やくノ一がどんでん返しなどの忍者屋敷の仕掛けからくりを案内します。忍術体験広場では、迫力の忍術実演ショーも楽しめます。

詳細については、HP観光三重をごらんください。
https://www.kankomie.or.jp' where id = '4IRGUWRHiPaQHQSzABxTA';
update content_bodies set title = 'Iga-ryu Ninja Museum', description = 'This is a ninja museum located in Ueno Park, which is home to many famous sites such as Iga Ueno Castle and the Haisei Hall. Ninja and kunoichi guide visitors through the tricks and mechanisms of the ninja house, including surprise elements. In the Ninja Experience Plaza, you can also enjoy thrilling ninja performance shows.

For more details, please visit the HP Kankou Mie.
https://www.kankomie.or.jp' where id = 'VrblCZdryQm_mGPCZpuXf';
update content_bodies set title = '松阪まるよし（三重県松阪市）', description = '牛一頭約600㎏から10㎏程度しか取れない極上ロースを使用した柔らなか肉質と甘みがたまらない松阪牛ロースステーキをはじめ、あっさり食べたいというご要望から誕生した松阪牛モモステーキなどが堪能できます。

