update content_bodies set title = '福王神社～福王山～東海自然歩道コース 山歩き', description = '菰野町にある福王山（標高597ｍ)に登った時の動画です。
２回目の福王山でしたが、下りは福王神社と反対側の東海自然歩道へ下りてぐるっと１周回れるコースがある事を最近知り、気分新たに楽しみにして登ってきました。
