update content_bodies set title = 'Self-Polishing Spot Mie - Owase Edition -', description = 'The World Heritage Site "Kumano Kodo - Iseji," which connects Ise to the Kumano Sanzan, is a pilgrimage route that appears in history. If you walk while imagining the travelers of old, you are sure to be captivated by its depth. At Yumekodo Owase, the mother''s lunch buffet is highly recommended!' where id = 'oBhRui6z1ptFRRk2quAqr';
