update content_bodies set title = '久慈良品vol.1　おぼろ昆布', description = 'あまちゃんの聖地、岩手県久慈市にはたくさんの魅力があります。
久慈市の魅力的な観光コンテンツを9本の短編動画にまとめました。
動画は映画監督として国内外でご活躍されている、長澤雅彦さんが制作されています。

ぜひ最後までご覧ください。

～「久慈良品」プロジェクトとは～
『「風景」「食べ物」「暮らしぶり」そして「人」など、地元の人には当たり前のものが、外の人から見ると、実は宝物だったりする』という視点で、観光関係者が集まり、その宝物を「久慈良品」として、国内外に広く発信していけるように取り組んだものです(9･Д･)j' where id = 'DuNjaMmkaAeln8OFbkpyk';
update content_bodies set title = 'Kuji Good Products vol.1 Oboro Kombu', description = 'Kuji City in Iwate Prefecture, the sacred place of ''Amachan'', has many attractions.
We have compiled the appealing tourist content of Kuji City into 9 short videos.
The videos are produced by Masahiko Nagasawa, who is active as a film director both domestically and internationally.

Please watch until the end.

~ What is the ''Kuji Good Products'' project ~
Gathering tourism stakeholders with the perspective that ''things that are taken for granted by locals can actually be treasures when viewed from the outside'', we have worked to widely promote these treasures as ''Kuji Good Products'' both domestically and internationally. (9･Д･)j' where id = 'HM2ywRVzCChK08kYHyMic';
