update content_bodies set title = '醸す・躍る・菊水', description = '見えないものの力が複雑に　絶妙に関わりあう発酵
それに寄り添い　伝統が紡ぎあげた　蔵人の動き
力強さと繊細さが織りなす　酒造りの神秘的な魅力
その躍動感と美しさを　新たなカタチで表現しました

「醸す・躍る・菊水」

Performer：舞姫☆ちあき☆ official website　https://www.maihimechiaki.com/
Creator：Hidekatsu Nakayama　https://hidekatsu.com/

produced by　KIKUSUI SAKE CO., LTD.　https://www.kikusui-sake.com/

菊水は新発田、北越後に根差し、発酵の力で大地の恵みを醸しながら、培われた文化を用いてお客様の健康、憩い、楽しみに貢献してまいります。

KIKUSUI, rooted in our city "Shibata," northern part of Niigata, brews the blessing of the nature with the power of fermentation and contributes to the health, relaxation and fun of our customers using the cultivated culture.' where id = 'Z5YtJTPzoRmLoxQo34DnN';
update content_bodies set title = 'Brewing, Dancing, Kikusui', description = 'The power of the unseen intricately and exquisitely interacts in fermentation.
