update content_bodies set title = '[Refresh] Kaga Hyakumangoku Sightseeing Route 20200817', description = 'The ''Kaga Hyakumangoku Sightseeing Route'' was born with the opening of the Nezumi Gate.
Among them, we will explore the ''Instagram-worthy course'' where you can fully enjoy the beautiful scenery of Kanazawa that you will want to capture in photos.' where id = 'xGn4ck2jTFVb13ENMVQ2y';
update content_bodies set title = '≪KYOKA音・語り≫　泉鏡花「照葉狂言」より', description = '慶長7年（1602年）、12世教如上人が東本願寺を興した後、加越能三ヵ国の門徒衆が建立した「東末寺」として出発。寛永11年（1634年）に現在地に寺基を定め、「金沢東別院」を舞台に、泉鏡花の美しく幻想的な物語が語られ、能と音楽、舞踊が絡んでいく夢の一夜をご覧ください。' where id = 'vxHftr7PGDYytvw1NjTHN';
update content_bodies set title = '≪KYOKA Sound & Story≫ From Izumi Kyōka''s ''Teruha Kyōgen''', description = 'In the 7th year of the Keichō era (1602), after the 12th generation of the Kyōnyo Shōnin established the Higashi Hongan-ji, it began as ''Higashimatsu-ji,'' built by the followers from the three provinces of Kaga, Etchū, and Noto. In the 11th year of the Kan''ei era (1634), the temple''s foundation was set in its current location. Please enjoy a dreamlike night where Izumi Kyōka''s beautiful and fantastical stories are told on the stage of ''Kanazawa Higashi Betsuin,'' intertwined with Noh, music, and dance.' where id = 'kgmGS5A4-48L5cIDjB1nO';
update content_bodies set title = '【らんらん走井】走井は今日も笑う！', description = '滋賀県栗東市走井(はしり)集落のイメージ動画です。
この里山は、いつも活き活きとしてたくさんの『笑顔』と出会えることを楽しんでいます。

