update content_bodies set title = '【兵庫県赤穂市PR動画】Ako Onsen,Japan「Feel Ako Time」', description = '赤穂温泉から望む瀬戸内の美しい水平線。
赤穂の自然や歴史、文化、グルメなどを体感。
“どこにでもあるかもしれない”“ここにしかないかもしれない”日常と非日常とが混ざり合う、ゆったりとした旅時間を連想させる映像です。ぜひご覧ください。

Learn more about Ako：http://ako-kankou.jp/' where id = 'FN2XRuyD71TYfb6rYkgn8';
update content_bodies set title = '[PR Video of Ako City, Hyogo] Ako Onsen, Japan ''Feel Ako Time''', description = 'A beautiful horizon of the Seto Inland Sea viewed from Ako Onsen.
Experience the nature, history, culture, and gourmet of Ako.
This video evokes a leisurely travel time that blends the everyday and the extraordinary, something that might be found anywhere or might only exist here. Please take a look.

Learn more about Ako: http://ako-kankou.jp/' where id = 'HooX7gdZF_2xREdwPoCWD';
update content_bodies set title = '【兵庫県赤穂市PR動画】「AKO SALT OF THE SEA」', description = '日本の食文化をはじめ、様々な分野で使用される『塩』。赤穂塩にまつわる歴史や製法、伝統的な製法によってできた塩に着目した新たな試みなど、塩の未来・可能性を表現しています。' where id = 'AOz8Z42ql9SiLD0LhYs9w';
update content_bodies set title = '[Hyogo Prefecture Ako City PR Video] ''AKO SALT OF THE SEA''', description = 'Salt, used in various fields including Japanese food culture.
This expresses the future and possibilities of salt, focusing on the history and production methods related to Ako salt, as well as new initiatives based on traditional production methods.' where id = 'NtVtxYwzVQvVk-Ckm15gs';
update content_bodies set title = 'Vol.0 - GOURMET 「Otaru Gourmet Report」 "OUR STORIES : from OTARU"', description = 'Yamashita Tomohiro, a native of Otaru and a very well-known figure in China, will introduce Otaru''s long-established gourmet restaurants in one minute! Triangle Market → Niikuraya → Yabuhan → Wakadori Jidai Naruto → Otaru Milk Plant → Masazushi and we''ll run through them all at once!

For more information on old gourmet restaurants that we are running out of time to introduce, please contact us.
Please see Mr. Yamashita''s channel below. 
https://www.bilibili.com/video/BV1eY4y1q7Ka/

---------------------------------------------------------------------------------
"OUR STORIES : from OTARU"
Vol.0 - GOURMET 「Otaru Gourmet Report」
---------------------------------------------------------------------------------
- Reported and Directed by　YAMASHITA TOMOHIRO
- Produced by　FUKUSHIMA KEISUKE

=========================================
【SUMMARY】
"OUR STORIES : from OTARU" was produced in 4K high definition.
This is a promotional video to attract tourists by Otaru City.

There are two 5-minute videos, "Otaru Version" and "KitaShiribeshi Version", 
and six 1-minute videos, including interviews.
The project consists of these 8 videos.

- ENGLISH SUBTITLED PLAY LIST (8videos/17m42s)
https://youtube.com/playlist?list=PLtVrA8df8XG1Ge3yugvLaMIkxSzLRyaZn

- 日本語字幕プレイリスト (8videos/17分42秒)
https://youtube.com/playlist?list=PLtVrA8df8XG2RqsmGOzLM6joHnm0VrRip

---------------------------------------------------------------------------------
