- 『City in Blue』 (4m57s) : https://youtu.be/SBJpswYzGjY
- 『PULSE OF LIFE IN KITASHIRIBESHI』 (4m51s) : https://youtu.be/VT5ykjUj30g

- OUR STORIES : from OTARU
　Vol.0 - GOURMET 「Otaru Gourmet Report」 (1m2s) : https://youtu.be/r2XHv9Knhv0
