update content_bodies set title = 'Vol.5 - KITASHIRIBESHI 「KitaShiribeshi and Otaru」 "OUR STORIES : from OTARU"', description = 'Shakotan Town, Kodaira Town, Yoichi Town, Niki Town, Akaigawa Village, and Otaru City. Of the municipalities belonging to the Shiribeshi Branch, these six municipalities along the Japan Sea coast are known as "KitaShiribeshi." In the past, herring was the common livelihood of this area, which is still overflowing with an abundance of marine and agricultural products. Wide-area branding of this area has great potential for the future.

---------------------------------------------------------------------------------
"OUR STORIES : from OTARU"
Vol.5 - KITASHIRIBESHI 「KitaShiribeshi and Otaru」
---------------------------------------------------------------------------------
- Interview with　TAKANO HIROYASU (Otaru University of Commerce)
- Produced by　FUKUSHIMA KEISUKE
- Directed by　ITO HIROKI
- Music by　NAKAMURA YOO

=========================================
【SUMMARY】
"OUR STORIES : from OTARU" was produced in 4K high definition.
This is a promotional video to attract tourists by Otaru City.

There are two 5-minute videos, "Otaru Version" and "KitaShiribeshi Version",
and six 1-minute videos, including interviews.
The project consists of these 8 videos.

