update content_bodies set title = 'Cycle Adventure Akan', description = '～阿寒摩周国立公園の豊かな自然を満喫できるまち「阿寒」～

火山・森・湖が織りなす豊かな自然、阿寒湖温泉に今も息づくアイヌ文化、
そしてサイクリングやカヌーなど、大自然をとことん楽しむさまざまなアクティビティ。
北海道を代表する温泉地・阿寒湖温泉を満喫できる楽しみ方をご紹介します！' where id = 'CAAZjlGnmTtAVLLD8M9fc';
update content_bodies set title = 'Cycle Adventure Akan', description = 'Experience the rich nature of Akan, a town where you can fully enjoy the abundant nature of Akan Mashu National Park.

The rich nature woven by volcanoes, forests, and lakes, the Ainu culture that still thrives in the Akan Lake hot springs,
and various activities such as cycling and canoeing to thoroughly enjoy the great outdoors.

We will introduce ways to enjoy the famous hot spring area of Hokkaido, Akan Lake Onsen!' where id = 'UP6Av63rillNbCVUjz0al';
