update content_bodies set title = 'お気持ちはわかるのですが・・・　＃草津温泉 #大家族フォーサイス家 ＃謝罪動画', description = '平素より、草津温泉をご愛顧いただきまして、
誠にありがとうございます。

世界中の皆様に、いくつかお詫びしたいことがございます。
それは・・・

動画にさせていただきました。
あたりまえのようなことがあたりまえじゃない日常
どうか、寛容な心で、最後までご覧いただき
ふふふっと笑ってご容赦いただけますと幸いです。

皆様により楽しめる温泉地観光地を目指して、
邁進して参ります。
今後とも草津温泉をご愛顧いただけますよう
切に願うばかりでございます。

