update content_bodies set title = 'I Understand Your Feelings, But... #KusatsuOnsen #ForsythFamily #ApologyVideo', description = 'Thank you very much for your continued support of Kusatsu Onsen.

We have a few things we would like to apologize for to everyone around the world.
That is...

We have made it into a video.
In a daily life where what seems obvious is not always so,
we would be grateful if you could watch until the end with a generous heart
and perhaps smile and forgive us.

We will continue to strive to make Kusatsu Onsen a more enjoyable tourist destination for everyone.
We sincerely hope for your continued support of Kusatsu Onsen.

Filming and Editing: COOTS

Filming SPOT: Yubatake
		 Bus Terminal Ashiyu
		 Lockheart Castle (Takayama Village)

Cast:
