update content_bodies set title = '赤城山エリアプロモーションムービー「Mount Akagi ROUND TRIP」（冬編）｜地域創生課｜群馬県', description = '赤城山広域振興協議会では、手島実優さん（女優／前橋市在住）を案内役として、赤城山の魅力をロードムービー風に伝える動画「Mount Akagi ROUND TRIP」を制作しました。
冬編では、スノーシューハイキングやワカサギ釣り、イルミネーションや雪の中で打ち上げられる花火など、冬ならではの赤城山の魅力を、旅情的なＢＧＭとともにロードムービー風にお伝えします。
手島さんと旅するように、冬の赤城山の風景をお楽しみください。

赤城山ポータルサイト　http://akagi-yama.jp/

●問い合わせ先：地域創生課（027-226-2352）

