update content_bodies set title = 'BIRD''S EYE3「５　藤原ダムを望む風景」｜建設企画課｜群馬県', description = '※群馬テレビで令和元年５月４日・５日に放映したものです。

私達の生活に欠かせない土木施設。県内には重要文化財に指定されたもの、最新の技術を駆使したものなど、将来に語り継ぐ価値のある土木施設が数多く存在します。
これら土木施設の役割や魅力を広く伝え、また将来を担う子どもたちに興味を持ってもらうため、県内の土木施設を紹介する番組を制作し放送することとなりました。
ドローンで撮影した映像などを駆使し、土木施設ならではのスケール感・ダイナミック感をお伝えします。

群馬県みなかみ町に位置する藤原ダムでは、年に一度、洪水期を迎える前にダムの放流設備が安全に作動するか確認するため点検放流を行います。
迫力あふれる放流映像をお楽しみください。

問い合わせ先：建設企画課（027-226-3531）' where id = 'XJdF-h5B2ByMkujUL9bVj';
update content_bodies set title = 'BIRD''S EYE3 ''5 View of Fujiwara Dam'' | Construction Planning Division | Gunma Prefecture', description = 'This was broadcasted on Gunma TV on May 4th and 5th, 2019.

Civil engineering facilities are essential to our lives. Within the prefecture, there are numerous civil engineering structures that are designated as important cultural properties, as well as those that utilize the latest technologies, all of which have value worth passing down to future generations.
To widely convey the roles and attractions of these civil engineering facilities and to spark interest in the children who will carry the future, we have produced a program introducing civil engineering facilities in the prefecture.
Using footage captured by drones, we will convey the unique scale and dynamism of civil engineering facilities.

At Fujiwara Dam, located in Minakami Town, Gunma Prefecture, an inspection release is conducted once a year before the flood season to ensure that the dam''s release equipment operates safely.
Enjoy the impressive release footage.

Contact: Construction Planning Division (027-226-3531)' where id = '6p9IU-OC8HiYQVb5JDSmE';
update content_bodies set title = 'BIRD''S EYE3「１０　上野スカイブリッジから望む風景」｜建設企画課｜群馬県', description = '※群馬テレビで令和元年６月８日・９日に放映したものです。

私達の生活に欠かせない土木施設。県内には重要文化財に指定されたもの、最新の技術を駆使したものなど、将来に語り継ぐ価値のある土木施設が数多く存在します。
これら土木施設の役割や魅力を広く伝え、また将来を担う子どもたちに興味を持ってもらうため、県内の土木施設を紹介する番組を制作し放送することとなりました。
ドローンで撮影した映像などを駆使し、土木施設ならではのスケール感・ダイナミック感をお伝えします。

上野村の上野スカイブリッジは、高さ90mの山あいに架かる観光用の吊り橋です。長さは225 mで、まほーばの森と川和自然公園を繋ぎます。４月～１１月の期間は10時～15時半の間で30分おきにシャボン玉が舞い上がり、現像的な風景を作り出します。
この時期は吹き込む風も心地よく、心のリフレッシュを求めて多くの観光客が訪れます。

問い合わせ先：建設企画課（027-226-3531）' where id = 'Tx-XuyhIqZ92NrDGfknIH';
update content_bodies set title = 'BIRD''S EYE3 ''10 View from Ueno Sky Bridge'' | Construction Planning Division | Gunma Prefecture', description = 'This was broadcasted on Gunma TV on June 8 and 9, 2019.

Civil engineering facilities are essential to our lives. Within the prefecture, there are numerous civil engineering structures that are designated as important cultural properties and those that utilize the latest technologies, all of which have value worth passing down to future generations.
To widely convey the roles and attractions of these civil engineering facilities and to spark interest in the children who will carry the future, we have decided to produce and broadcast a program introducing civil engineering facilities in the prefecture.
Using footage captured by drones, we will convey the unique scale and dynamism of civil engineering structures.

The Ueno Sky Bridge in Ueno Village is a tourist suspension bridge that spans 90 meters high in the mountains. It is 225 meters long and connects the Mahobano Mori and Kawawa Nature Park. From April to November, soap bubbles are released every 30 minutes between 10:00 AM and 3:30 PM, creating a magical landscape.
During this time, the breeze is also pleasant, attracting many tourists seeking a refreshing experience for the mind.

Contact: Construction Planning Division (027-226-3531)' where id = '7U1lwFkt_oUUQITJVteJN';
update content_bodies set title = 'BIRD''S EYE3「１５　土合橋から土合砂防堰堤を望む風景」｜建設企画課｜群馬県', description = '※群馬テレビで令和元年７月１３日・１４日に放映したものです。

私達の生活に欠かせない土木施設。県内には重要文化財に指定されたもの、最新の技術を駆使したものなど、将来に語り継ぐ価値のある土木施設が数多く存在します。
これら土木施設の役割や魅力を広く伝え、また将来を担う子どもたちに興味を持ってもらうため、県内の土木施設を紹介する番組を制作し放送することとなりました。
ドローンで撮影した映像などを駆使し、土木施設ならではのスケール感・ダイナミック感をお伝えします。

群馬県みなかみ町にある土合砂防堰堤は、岩盤が露出した部分に設置されたアーチ式の堰堤です。半円のような形で、水が中央に集まる堰堤は県内でも珍しい作りです。
提長112m提高11mで比較的小さな堰堤ですが、その珍しい形も相まって流れる様子は圧巻です。
爽やかな水の音と緑の自然。夏には涼を求めて足を運んでみてはいかがでしょうか。

問い合わせ先：建設企画課（027-226-3531）' where id = 'GLERU3me7dj7l8xvWf7OL';
update content_bodies set title = 'BIRD''S EYE3 ''15 View of the Doai Bridge from the Doai Sabo Dam'' | Construction Planning Division | Gunma Prefecture', description = 'This was broadcasted on Gunma TV on July 13 and 14, 2019.

Civil engineering facilities are essential to our lives. Within the prefecture, there are numerous civil engineering structures that are designated as important cultural properties, as well as those that utilize the latest technologies, all of which have value to be passed down to future generations.
To widely convey the roles and attractions of these civil engineering facilities and to spark interest in the children who will carry the future, we have decided to produce and broadcast a program introducing civil engineering facilities in the prefecture.
Using footage captured by drones, we will convey the unique scale and dynamism of these civil engineering structures.

The Doai Sabo Dam, located in Minakami Town, Gunma Prefecture, is an arch dam installed on exposed bedrock. Its semi-circular shape allows water to collect in the center, making it a rare structure within the prefecture.
Although it is a relatively small dam, measuring 112m in length and 11m in height, the sight of the flowing water, combined with its unusual shape, is truly impressive.
With the refreshing sound of water and lush greenery, why not visit during the summer to seek some coolness?

Contact: Construction Planning Division (027-226-3531)' where id = 'Rr4aaK1dqj-4KZ_06ervH';
update content_bodies set title = 'BIRD''S EYE3「２３　四季の移りを感じる風景」｜建設企画課｜群馬県', description = '※群馬テレビで令和元年９月７日・８日に放映したものです。

私達の生活に欠かせない土木施設。県内には重要文化財に指定されたもの、最新の技術を駆使したものなど、将来に語り継ぐ価値のある土木施設が数多く存在します。
これら土木施設の役割や魅力を広く伝え、また将来を担う子どもたちに興味を持ってもらうため、県内の土木施設を紹介する番組を制作し放送することとなりました。
ドローンで撮影した映像などを駆使し、土木施設ならではのスケール感・ダイナミック感をお伝えします。

いずみ緑道は、大泉町を南北に縦断する総延長2.8キロメートルの道です。緑道内は100種類を超える樹木に彩られ、四季の移り変わりを人々に告げます。
その傍らには、花の名前が付けられた通りがあります。昭和14年、日本に戦争の足音が迫る頃、飛行機を運ぶために作られたという仙石川岸線が開通しました。それがこのいずみ緑道の元なのです。

問い合わせ先：建設企画課（027-226-3531）' where id = 'sjxNzFPkc2oDfzj5en1Cm';
update content_bodies set title = 'BIRD''S EYE3 ''23 Landscapes that Feel the Change of Seasons'' | Construction Planning Division | Gunma Prefecture', description = '*This was broadcasted on Gunma TV on September 7 and 8, 2019.

Civil engineering facilities are essential to our lives. Within the prefecture, there are numerous civil engineering structures that are designated as important cultural properties and those that utilize the latest technologies, all of which have value to be passed down to future generations.
To widely convey the roles and attractions of these civil engineering facilities and to spark interest in the children who will bear the future, we have decided to produce and broadcast a program introducing civil engineering facilities in the prefecture.
Using footage captured by drones, we will convey the unique scale and dynamism of civil engineering facilities.

The Izumi Greenway is a 2.8-kilometer-long path that runs north-south through Oizumi Town. The greenway is adorned with over 100 species of trees, signaling the changes of the seasons to the people.
Alongside it, there are streets named after flowers. In 1939, as the sounds of war approached Japan, the Sengokugawagishi Line was opened, which was built to transport airplanes. This is the origin of the Izumi Greenway.

Contact: Construction Planning Division (027-226-3531)' where id = 'VUGVJQaRdy8Iho4hC3e8w';
update content_bodies set title = 'BIRD''S EYE3「２２　利根川水制工を望む風景」｜建設企画課｜群馬県', description = '※群馬テレビで令和元年８月３１日・９月１日に放映したものです。

私達の生活に欠かせない土木施設。県内には重要文化財に指定されたもの、最新の技術を駆使したものなど、将来に語り継ぐ価値のある土木施設が数多く存在します。
これら土木施設の役割や魅力を広く伝え、また将来を担う子どもたちに興味を持ってもらうため、県内の土木施設を紹介する番組を制作し放送することとなりました。
ドローンで撮影した映像などを駆使し、土木施設ならではのスケール感・ダイナミック感をお伝えします。

利根川は前橋市を流れる、日本を代表する河川です。そこからは風光明媚な赤城山を望むことができます。
いまは穏やかな風景が広がりますが、利根川は急流と曲がりくねった形状から古来より暴れ川としての悪名もありました。そのたびに人々は知恵を絞り、利根川の護岸工事を進めたのです。高さ1メートルから4メートルの石積み群は、過去から受け継ぐ治水術であり、その技術は現在も人々を守り続けています。

問い合わせ先：建設企画課（027-226-3531）' where id = 'J3x1dj3VUbgjuSg_0T6_K';
update content_bodies set title = 'BIRD''S EYE3 ''22 Landscape Overlooking the Tone River Water Control Works'' | Construction Planning Division | Gunma Prefecture', description = 'This was broadcasted on Gunma TV on August 31 and September 1, 2019.

Civil engineering facilities are essential to our lives. Within the prefecture, there are numerous civil engineering structures that are designated as important cultural properties and those that utilize the latest technologies, all of which have value worth passing down to future generations.
To widely convey the roles and attractions of these civil engineering facilities and to spark interest in the children who will carry the future, we have produced a program introducing civil engineering facilities in the prefecture.
Using footage captured by drones, we will convey the unique scale and dynamism of civil engineering structures.

The Tone River is a representative river of Japan that flows through Maebashi City. From there, one can enjoy a scenic view of Mount Akagi.
Currently, a tranquil landscape spreads out, but the Tone River has historically been notorious as a turbulent river due to its swift currents and winding shape. Each time, people have devised ways to advance the riverbank construction of the Tone River. The stone walls, ranging from 1 to 4 meters in height, are a legacy of flood control techniques passed down from the past, and that technology continues to protect people today.

Contact: Construction Planning Division (027-226-3531)' where id = 'jptIZRjB-nDee1OWiJsPf';
update content_bodies set title = 'BIRD''S EYE3「２９　コンクリートアーチのフォルムと自然が織りなす風景」｜建設企画課｜群馬県', description = '※群馬テレビで令和元年１０月１９日・２０日に放映したものです。

私達の生活に欠かせない土木施設。県内には重要文化財に指定されたもの、最新の技術を駆使したものなど、将来に語り継ぐ価値のある土木施設が数多く存在します。
これら土木施設の役割や魅力を広く伝え、また将来を担う子どもたちに興味を持ってもらうため、県内の土木施設を紹介する番組を制作し放送することとなりました。
ドローンで撮影した映像などを駆使し、土木施設ならではのスケール感・ダイナミック感をお伝えします。

下仁田町には、日本人がどこか懐かしいと感じる、一本のコンクリートアーチの橋から醸し出される昭和の風景があります。緑深い美しい山々と清流に囲まれ、時間の流れを忘れてしまいそうな雰囲気が流れています。
橋から視線を落とせば、そこにはギザギザの岩が目に入ります。逆転層と呼ばれるこの地層は、太古より堆積した地層が反転した珍しい風景なのです。

問い合わせ先：建設企画課（027-226-3531）' where id = 'GhHxqUDPh4OM7FevwvZXz';
update content_bodies set title = 'BIRD''S EYE3 "29 Concrete Arch Forms and Landscapes Woven with Nature" | Construction Planning Division | Gunma Prefecture', description = 'This was broadcasted on Gunma TV on October 19 and 20, 2019.

Civil engineering facilities are essential to our lives. Within the prefecture, there are numerous civil engineering structures that are designated as important cultural properties and those that utilize the latest technologies, all of which hold value to be passed down to future generations.
To widely convey the roles and attractions of these civil engineering facilities and to spark interest in the children who will bear the future, we have produced and broadcast a program introducing civil engineering facilities in the prefecture.
Using footage captured by drones, we will convey the scale and dynamism unique to civil engineering facilities.

In Shimonita Town, there is a nostalgic Showa-era landscape emanating from a single concrete arch bridge that evokes a sense of familiarity for the Japanese. Surrounded by beautiful, lush green mountains and clear streams, it creates an atmosphere that makes one forget the passage of time.
Looking down from the bridge, one can see jagged rocks. This layer, known as the inverted layer, is a rare landscape where ancient sedimentary layers have been flipped over.

