桐生市にある山上城址公園は、石垣や土塁の跡が鎌倉時代から戦国期にかけて存在した山上城の面影を伝えてくれます。
現在は緩やかな丘陵を活かしたローラー滑り台やロープクライミングなどの遊具が充実し、地域住民の憩いの場として愛される存在となっています。また公園にはおよそ150本の蝋梅があり２月の下旬まで少し早い春の訪れを楽しむことが出来ます。

