update content_bodies set title = 'BIRD''S EYE3 ''45 Enjoying Nature and History'' | Construction Planning Division | Gunma Prefecture', description = 'This was broadcasted on Gunma Television on February 22 and 23, 2020.

Civil engineering facilities are essential to our lives. Within the prefecture, there are numerous civil engineering structures that are designated as important cultural properties and those that utilize the latest technologies, all of which have value to be passed down to future generations.
To widely convey the roles and attractions of these civil engineering facilities and to spark interest in the children who will carry the future, we have decided to produce and broadcast a program introducing civil engineering facilities in the prefecture.
Using footage captured by drones, we will convey the unique scale and dynamism of civil engineering structures.

Yamajō Castle Ruins Park in Kiryu City preserves the remnants of stone walls and earthen mounds that tell the story of Yamajō Castle, which existed from the Kamakura period to the Sengoku period.
Currently, the park is equipped with various playground equipment such as a roller slide and rope climbing that take advantage of the gentle hills, making it a beloved place for local residents to relax. Additionally, the park features approximately 150 wintersweet trees, allowing visitors to enjoy an early arrival of spring until late February.

