update content_bodies set title = 'BIRD''S EYE3 "37 View of Mount Myogi from Nishinomaki Ohashi" | Construction Planning Division | Gunma Prefecture', description = 'This was broadcasted on Gunma TV on December 14 and 15, 2019.

Civil engineering facilities are essential to our lives. Within the prefecture, there are numerous civil engineering structures that are designated as important cultural properties and those that utilize the latest technologies, all of which have value worth passing down to future generations.
To widely convey the roles and attractions of these civil engineering facilities and to spark interest in the children who will carry the future, we have decided to produce and broadcast a program introducing civil engineering facilities in the prefecture.
Using footage captured by drones, we will convey the unique scale and dynamism of civil engineering structures.

The Matsuidakaruizawa Line is a road that connects Matsuidamachi in Gunma Prefecture and Karuizawamachi in Nagano Prefecture. This road, with its steep and winding curves, rapidly gains elevation towards Karuizawamachi.
Just before reaching the top of the slope is Nishinomaki Ohashi. From the car window, you can see the beautiful Mount Myogi, which delights us with its seasonal appearances.
Oh! But please, drivers, keep your eyes on the road and drive safely!

