update content_bodies set title = 'BIRD''S EYE3「４７　西毛広域幹線道路がつくりだす風景」｜建設企画課｜群馬県', description = '※群馬テレビで令和２年３月７日・８日に放映したものです。

私達の生活に欠かせない土木施設。県内には重要文化財に指定されたもの、最新の技術を駆使したものなど、将来に語り継ぐ価値のある土木施設が数多く存在します。
