update content_bodies set title = 'BIRD''S EYE3 ''47 The Landscape Created by the Nishi-Maeda Wide Area Trunk Road'' | Construction Planning Division | Gunma Prefecture', description = 'This was broadcasted on Gunma TV on March 7 and 8, 2020.

Civil engineering facilities are essential to our lives. Within the prefecture, there are numerous civil engineering structures that are designated as important cultural properties and those that utilize the latest technologies, all of which have value worth passing down to future generations.
To widely convey the roles and attractions of these civil engineering facilities and to spark interest in the children who will carry the future, we have decided to produce and broadcast a program introducing civil engineering facilities in the prefecture.
Using footage captured by drones, we will convey the unique scale and dynamism of civil engineering structures.

The Nishi-Maeda Wide Area Trunk Road is a 27.8-kilometer route connecting Maebashi City and Tomioka City. The Maebashi and Tomioka sections are already supporting the regional economy as part of the local transportation network, and the Takasaki and Annaka sections, which are expected to play a significant role in Gunma''s future, are currently undergoing diligent work aiming for full opening.
In the Takasaki section, construction of the elevated bridge is progressing towards the day it will reveal its form, while in the Annaka section, impressive tunnel construction is underway.
This road is expected to take Gunma Prefecture to the next stage, and the anticipation is unending.

