update content_bodies set title = 'TOKYO LOVERS 2023 | SNAP VIDEO | Cinema Line SONY FX3 | BLACK MIST No.05  ||', description = '映像制作に取り組むと、細部にこだわりすぎてしまい、作品を完成させるための時間が足りなくなることがよくあります。これを克服するために、撮影時間を2時間、編集時間を2時間に制限し、音や色にこだわりすぎずにシネマティックな映像を作成することに挑戦しました。

私の世界を楽しんでいただければ幸いです。応援ありがとうございます。
▼subscribe: https://www.youtube.com/@kosei79
FOLLOW ME ON Instagram→ https://www.instagram.com/k0se179/

普段、仕事で映像制作をしていると、どんどんとこだわりが強くなってしまい、細部にこだわり過ぎて、作品を制作するのに費やす時間が膨大になり、次第に作品を世に出す時間が足りなくなってしまいます。そこで今回は、自分に「２時間の撮影時間と２時間の編集時間」という縛りを設け、音声や色にこだわりすぎず、オール手持ち撮影で子供がお絵描きをするかのような気分で、思うがままに東京を舞台にしたストリート映像を制作しました。オールマニュアル撮影でピンも敢えて外れたままの素材を使用。ほんわかと気分が上がる音楽と2023年の東京が合わさると、どこかコロナ以前の世界観に戻った（より進化した？）世界になってきたなと、前向きな気分になりました！肩の力を抜いて映像をお楽しみください。

Where I get my song from Artlist.io: https://bit.ly/36b478B
(↑You can get 2 extra months free)

