update content_bodies set title = 'Akan Soul', description = '秋・冬・夏と3シーズン、計1ヶ月撮影した「Akan Soul」。北海道阿寒湖温泉地域とアイヌ文化の日常を追ったノンバーバルドキュメンタリーです☺️非言語で、説明なしで人々の日常が紡ぐ物語が伝えられるか、とても挑戦的な試みでした。この作品を通して多くの人と関われ、文化の深いところまで勉強させて頂きました。

あらためて、自分の心が動く作品を時間と情熱をかけて作っていきたいと思いました！
北海道の阿寒湖温泉地域を３シーズンに渡り撮影したノンバーバル・ドキュメンタリー。美しい自然、阿寒湖温泉地域の木彫りの職人、生活を営む人々、アイヌの文化や伝統、そこに住む人々の熱量に魅了され、僕はカメラを回した。

阿寒湖温泉：http://ja.kushiro-lakeakan.com
阿寒湖アイヌコタン：https://www.akanainu.jp
阿寒湖アイヌシアターイコロ：https://www.akanainu.jp/about/ikoro
豆腐工房まるふく：https://ja.kushiro-lakeakan.com/eat_souvenir/16078/

この動画の制作にご協力下さった皆様に改めて感謝を申し上げます。自分自身とても学びがありたくさん勉強になりました、ありがとうございます！！！

Awards and Official Selection:
2023 Global Stage Hollywood 映画祭 Official Selection
2024 日本国際観光映画祭の国内部門ドキュメンタリー分野「最優秀賞」
2024 日本国際観光映画祭の国際部門Tourism product分野「ブロンズ」
2024 Tokyo Lift-Off Film Festival, Official Selection 
2024 Busan New Wave Short Film Festival, Finalist: Best Director, Best Cinematography 
2024 Incheon International Short Film Festival, Winner: Best short film, Best Experimental
2024 Albania, LuminaFlicks International Short Film Fest, Winner: Best Short Film 5-10 Minutes
2024 Copenhagen NATURE & CULTURE International Poetry Film Festival, Official Selection
2024 Spain, Terres Travel Festival, Best Short Film in documentary
2024 Austrarlia, International Multicultural Film FestivalでThe Best Short Documentary Film
2024 Portugal, ART&TUR - International Tourism Film Festival, 1st Prize in the Cultural Tourism category
2025 South Africa, International Tourism Film Festival Africa, Finalist


Special Thanks:
Kengo Takiguchi, Ayako Inoue, Akanko Onsen, Akanko Ainu Kotan, Ainu Theater Ikor and Dancers, Tofu Kobo Marufuku, Yukio Fujito, Kumiko san, Yoshiko Fujisawa, Masao Nishida, Kayoko Nishida, Keiko Kobayashi, Yuko Nakagawa, Koichi Kikuchi, Chika Nishiyama, Kayo san, Pete san, Saki san, and everyone who helped in the making of this film

I filmed a non-verbal documentary over three seasons in the Lake Akan Onsen area of Hokkaido, which offers a wealth of captivating features that satisfy your desire for knowledge and exploration of Ainu culture. Additionally, many traditional Japanese artisans contribute to the creation of this unique atmosphere. This film captures the beautiful nature, Ainu culture and traditions, as well as the passion of the people living there.

■Web・SNS
Website: https://www.yuichiishida.com
Instagram: https://instagram.com/you_ishida
Vimeo: https://vimeo.com/yuichiishida
Twitter: https://twitter.com/yuichiishida3' where id = 'Fg4nb8tcZGSQEE9mEM8Oi';
update content_bodies set title = 'Akan Soul', description = 'Akan Soul, filmed over three seasons in autumn, winter, and summer for a total of one month. This is a non-verbal documentary that follows the daily life of the Ainu culture in the Lake Akan Onsen area of Hokkaido. ☺️ It was a very challenging attempt to convey the stories woven by people''s daily lives without words or explanations. Through this work, I was able to connect with many people and learn deeply about the culture.

Once again, I felt the desire to create works that move my heart with time and passion!
A non-verbal documentary filmed over three seasons in the Lake Akan Onsen area of Hokkaido. Captivated by the beautiful nature, the woodcarvers of the Lake Akan Onsen area, the people living their lives, the Ainu culture and traditions, and the passion of the people who live there, I turned the camera.

Lake Akan Onsen: http://ja.kushiro-lakeakan.com
Akan Lake Ainu Kotan: https://www.akanainu.jp
Akan Lake Ainu Theater Ikoro: https://www.akanainu.jp/about/ikoro
Tofu Kobo Marufuku: https://ja.kushiro-lakeakan.com/eat_souvenir/16078/

I would like to express my gratitude once again to everyone who cooperated in the production of this video. I learned a lot and gained so much knowledge, thank you!!!

