update content_bodies set title = '只見線｜秘境をゆく - The Last Hidden Line of Japan', description = '静けさに包まれた奥会津を走る、秘境路線「只見線」。
残雪の季節、春の気配とともに列車は山あいを進みます。健気に、ゆっくりと。

