update content_bodies set title = 'I Can''t Just Hide', description = 'Koka Film Festival 2023 [Creator Category] Semi-Grand Prix
This time, I filmed in a drama style while exploring the city, focusing on the beloved rural landscapes of Koka. I hope you enjoy the various faces of Koka''s townscape, featuring famous spots such as Abihiyama Shrine, Shingu Shrine''s front gate, Rokakudo, the ruins of Minakuchi Okayama Castle, Tonomi Da Tea Garden, Shigaraki Kogen Railway, and Cafe Ogama.' where id = 'x3V8e2sXjEFFMkFXlTYbR';
update content_bodies set title = 'JOINKOKA', description = '甲賀映像祭2023【クリエーター部門】水口青年会議所理事長賞
矢川神社、水口岡山城、庚申山など。見るもの自体はもちろん、伝えてくれる忍者たちが大きな魅力です。そして、見るだけじゃなく参加して、忍者になれる。
やってるほうが本当に楽しいと思う事を繰り出して「集え」と仲間にさそってくれているような、聞いてるだけ見てるだけじゃなく、仲間に入って体感できる魅力を、タイトルの「JOINKOKA」に込めました。' where id = 'aXgVz3Hc4K2SexlviQj5B';
update content_bodies set title = 'JOINKOKA', description = 'Koka Film Festival 2023 [Creator Category] President''s Award of the Minakuchi Junior Chamber
