update content_bodies set title = '令和３年度ツーリズム商談会プレゼンテーション動画①（大分市）', description = '別府・由布に隣接し、県内への周遊が便利な大分市には、1,000頭を越えるおサルが暮らす「高崎山自然動物園」や水族館など子どもから大人まで楽しめるスポットがあります。さらに関あじ・関さばやとり天といったグルメに、県下有数の源泉数を誇る温泉も楽しめ、工業都市でありながら様々な魅力をそなえています。' where id = '9Pv8duDmucnRSpT0i-BPm';
update content_bodies set title = 'Presentation Video of the 2021 Tourism Business Meeting ① (Oita City)', description = 'Oita City, adjacent to Beppu and Yufu, offers convenient access for touring within the prefecture. It features attractions enjoyable for all ages, such as the "Takasakiyama Natural Zoo," home to over 1,000 monkeys, and an aquarium. Additionally, visitors can savor local delicacies like Seki mackerel and Seki horse mackerel, as well as enjoy hot springs boasting one of the highest numbers of sources in the prefecture, making it a city rich in various attractions despite being an industrial hub.' where id = '2TCi7KhncEU9iN8829HJm';
