update content_bodies set title = '令和３年度ツーリズム商談会プレゼンテーション動画 ③(中津市）', description = '中津市は、山国川の源流から河口まで続く渓谷美と城下町の歴史が織り成す魅力あふれるところです。軍師黒田官兵衛・福澤諭吉ゆかりの中津城下町や、奇岩の渓谷が美しい絵巻物のような風景をつくる日本遺産、名勝耶馬渓などがあります。メイプル耶馬サイクリングロードは耶馬渓の景色と歴史を体感できる人気スポットです。' where id = 'n2jNlIivb-xnL6M0i9MUd';
update content_bodies set title = 'Presentation Video of the 2021 Tourism Business Meeting ③ (Nakatsu City)', description = 'Nakatsu City is a place full of charm, woven together by the beautiful gorge that stretches from the source to the mouth of the Yamakuni River and the history of its castle town. There are attractions such as Nakatsu Castle Town, associated with strategist Kuroda Kanbei and Yukichi Fukuzawa, and the Japan Heritage site, Yabakei, known for its stunning landscapes created by bizarre rock formations. The Maple Yaba Cycling Road is a popular spot where you can experience the scenery and history of Yabakei.' where id = 'mFw1QfvleNcB5pTnv4-l5';
