update content_bodies set title = '浜田城跡 〜浜田の歴史にタイムスリップ〜', description = '浜田市街の中心、城山公園の山の上にある浜田城跡は、1620年から約250年間続いたお城で、現在は石垣のみが残り、公園として日本海や浜田の町並みを見晴らすことのできるスポットとなっています。動画の後半に、かつての浜田城の北前船貿易港、外ノ浦にある「浜田の夕日自動販売機」も出てきますので、ぜひご覧ください！

