update content_bodies set title = 'Hamada Castle Ruins - Time Slip into Hamada''s History -', description = 'The Hamada Castle Ruins, located on top of Mount Jōyama in the center of Hamada city, is a castle that lasted for about 250 years from 1620. Currently, only the stone walls remain, and it has become a spot where you can overlook the Sea of Japan and the townscape of Hamada as a park. In the latter part of the video, you will also see the ''Hamada Sunset Vending Machine'' located in the port of Kitamaebune trade, known as Soto-no-Ura, which was once part of Hamada Castle. Please take a look!

◎ [Feature] Let''s GO to Hamada Castle Ruins! - Time Slip into Hamada''s History -
