update content_bodies set title = '西野七瀬｜まちに、泊まる【旅色Movie】', description = '宿だけでなく、その周辺のまちも楽しむ「分散型ホテル」を特集。西野七瀬さんが温泉街全体を1つの旅館に見立てている熊本県の「黒川温泉」を散策する旅ムービーです。

❀西野七瀬 Profile❀
1994年生まれ、大阪府出身。2011年に乃木坂46の第一期オーディションに合格。2015年からはファッション誌『non-no』（集英社）で専属モデルとしても活動（2022年3月号で卒業）。2018年12月に乃木坂46を卒業した後は、主演作のAmazon Originalドラマ「ホットママ」、映画「孤狼の血 LEVEL2」、ドラマ「言霊荘」（テレビ朝日系）など話題作への出演が続いている。2022年に「孤狼の血 LEVEL2」で第45回日本アカデミー賞 優秀助演女優賞・新人俳優賞を受賞。2022年4月からドラマ「恋なんて、本気でやってどうするの？」（関西テレビ・フジテレビ系）に出演のほか、5月より舞台「みんな我が子」-ALL My Sons-への出演、また映画「恋は光」が6月17日より全国で公開される。

