update content_bodies set title = '上白石萌歌｜奥薩摩・伊佐のふわり旅日和 鹿児島県伊佐市 60秒Ver【旅色Movie】', description = '鹿児島県本土の最北地に位置します。川内川（せんだいがわ）をはじめとする清流に囲まれ、美しい自然景観が魅力です。寒暖差の激しい盆地後系で、2020年の最低気温がマイナス6.4℃（12月26日）、最高平均気温は37.6℃（8月18日）と気温差がはっきり。その環境が豊かな食文化を育み、「薩摩の米蔵」としても有名です。また、“東洋のナイアガラ”とも呼ばれる「曽木の滝」、５月～９月の間にしか姿を現さない幻の建物「曽木発電所遺構」など歴史ロマンの詰まったまちでもあります。自然、食、カルチャーと、多彩な魅力にあふれる伊佐市の旅へ出かけてみませんか。

