update content_bodies set title = 'Moka Kamishiraishi | A Fluffy Travel Day in Okusatsuma, Isa City, Kagoshima Prefecture 60-Second Version [Tabiiro Movie]', description = 'Located in the northernmost part of Kagoshima Prefecture. Surrounded by clear streams such as the Sendai River, it boasts beautiful natural scenery. With significant temperature differences in this basin area, the lowest temperature in 2020 was -6.4°C (December 26), while the highest average temperature was 37.6°C (August 18), clearly showing the temperature variation. This environment nurtures a rich food culture, and it is also famous as the ''Satsuma Rice Storehouse.'' Additionally, it is a town filled with historical romance, featuring the ''Sogi Falls,'' known as the ''Niagara of the East,'' and the elusive ''Sogi Power Plant Ruins,'' which only appear between May and September. Why not embark on a journey to Isa City, overflowing with diverse attractions such as nature, food, and culture?' where id = 'ufJjKENhKlyrg6y3AUMbX';
