update content_bodies set title = '福本莉子｜自慢したくなる旅先、見つけた！ 恐竜の郷・熊本県御船町へ【旅色Movie】', description = '日本で初めて肉食恐竜の歯の化石が発見された恐竜の郷・御船町は、町の形を真上から見ると恐竜のように見える町。実は恐竜好きだという俳優の福本莉子さんが訪れ、豊かな自然やご当地グルメも楽しみながら、思わず誰かに自慢したくなる特別な体験をしに行きます。

┈┈福本莉子 Profile┈┈
2000年11月25日生まれ、大阪府出身。第8回「東宝シンデレラ」オーディションでグランプリと集英社賞をダブル受賞しデビュー。2018年に映画「のみとり侍」でスクリーンデビュー。その後も映画「センセイ君主」、「今夜、世界からこの恋が消えても」、ドラマ「消えた初恋」（テレビ朝日系）、「トリリオンゲーム」（TBS）などの話題作に出演。また、同年には初舞台となるミュージカル「魔女の宅急便」で初主演を務めた。フジテレビ系10月期月9ドラマ「ONE DAY～聖夜のから騒ぎ」に新人記者の立葵査子役で出演中。

