┈┈Riko Fukumoto Profile┈┈
Born on November 25, 2000, from Osaka Prefecture. She debuted after winning both the Grand Prix and Shueisha Award at the 8th ''Toho Cinderella'' audition. She made her screen debut in the 2018 film ''Samurai Shokudo.'' Since then, she has appeared in notable works such as ''Sensei Kunshu,'' ''Even If This Love Disappears from the World Tonight,'' the drama ''The Disappeared First Love'' (TV Asahi), and ''Trillion Game'' (TBS). In the same year, she also starred in her first stage musical, ''Kiki''s Delivery Service.'' Currently, she is appearing as the rookie reporter Tachi Aoi in the Fuji TV October drama ''ONE DAY - A Ruckus on Christmas Eve.''

