This area, consisting of Tottori City, Iwami Town, Wakasa Town, Chizu Town, Yazu Town in Tottori Prefecture, and Shinonsen Town and Kami Town in Hyogo Prefecture, is home to some of Japan''s most stunning landscapes, including the country''s largest sand dune, the "Tottori Sand Dunes," the breathtaking "Uradome Coast," where you can enjoy delicious local mountain cuisine at "Mitaki-en," the leisurely train journey on the "Wakasa Railway," the renowned hot spring "Yumura Onsen" with over 1,000 years of history, and the shining "folk crafts" of Tottori, making this area full of attractions.

