Born on July 18, 1991, in Fukuoka City, Fukuoka Prefecture. Debuted as an exclusive model for the fashion magazine ''CanCam'' in 2009. Started her acting career in 2011. The following year, she gained attention for her first film appearance in ''Kirishima, Bukatsu Yamerutteyo.'' In 2025, she will star in the Hulu original ''Otona ni Natte mo,'' which will be available from April, and will also appear in the MBS/TBS drama ''Gurende Meshi,'' showcasing her wide-ranging talents in dramas, films, commercials, magazines, and narration.

