┈┈Sara Minami Profile┈┈
Born on June 11, 2002, in Tokyo. She began her modeling career in 2014 and made her acting debut in the film ''The Little Ones Are Born to Us'' (2017). She received numerous film awards, including the Hochi Film Award and the Blue Ribbon Award, for her lead role in the film ''Shino Can''t Say Her Own Name'' (2018). She gained attention for her appearances in TBS Sunday Theater ''Dragon Sakura'' (2021) and NHK Taiga Drama ''Kamakura-dono no 13-nin'' (2022). In 2024, she will appear again in the NHK Taiga Drama ''Hikaru Kimi e'' as the protagonist Murasaki Shikibu''s daughter, Fujiwara no Kenko. DMMTV''s ''Gedo no Uta'' and ABEMA''s ''Wakatte Itemo: The Shapes of Love'' are currently available.

