update content_bodies set title = '桜井日奈子｜千葉の東に教えたくなる旅先あり。東金というベストプレイス【旅色Movie】', description = '今年デビュー10周年を迎える桜井日奈子さんが、千葉県の東部に位置する東金市（とうがねし）を巡る1泊2日の旅に出かけました。都心から車や電車でわずか1時間ほどのロケーションにある東金市。こんな近場で、深呼吸したくなるような豊かな自然、知的好奇心をくすぐる歴史、そして、とっておきのグルメが揃うことに驚く人も多いのでは？ 2024年は市制施行70周年の記念の年、1年を通してさまざまなイベントや記念グッズが企画されていることにも注目を。

┈┈桜井日奈子Profile┈┈
岡山県出身。2014年「岡山美少女・美人コンテスト」の美少女グランプリを受賞し、「岡山の奇跡」として注目を集める。今年デビュー10周年を迎え、初めての水着撮影に挑戦した写真集『鴇色』が発売されるなど新境地を切り開いている。2024年夏クールに放送されたテレビドラマ『マル秘の密子さん』（日本テレビ）にも出演。11月22日から東京・大阪で行われる舞台『138億年未満』にヒロインで出演が決まっている。人気映画シリーズ『キングダム 大将軍の帰還』、12月公開予定の『聖☆おにいさん ホーリーメンVS悪魔軍団』に出演。

