Born on September 27, 1991, in Tokyo. Debuted in 2010. In 2014, she was selected as the heroine of ''Kamen Rider Drive,'' marking the beginning of her serious acting career. In 2018, she won the Best Supporting Actress Award at the Drama Grand Prix for ''Ossan''s Love.'' She has also starred in dramas such as ''Shogi Meshi,'' ''The Buzz Family Across the Street,'' and ''In the Next Life, I Will Definitely Do It Right.'' Additionally, she has been active as an exclusive model for the fashion magazine ''MORE'' since 2015.

