update content_bodies set title = '桜庭ななみ｜優しくておもしろい里山タウン！ 栃木・那珂川町の魅力に心がトロリ【旅色Movie】', description = '栃木県の北東部に位置し、天然鮎遡上日本一を誇る清流・那珂川や、八溝山系に抱かれた豊かな自然が魅力の那珂川町。多くが西向きに構える馬頭温泉郷は、沈みゆく夕日を眺められる「夕焼け温泉郷」とも言われ、知られざる魅力が満載のまさに栃木の秘境です。江戸時代から今も受け継がれる小砂焼のろくろ体験をしたり、浮世絵を展示する馬頭広重美術館で芸術に触れたりと、那珂川町の魅力が詰まった旅に桜庭ななみさんが出かけます。

