▼ Yui Aragaki
Born on June 11, 1988, in Okinawa. After working as a model for the teen magazine ''Nicola'' (Shinchosha), she focused on her acting career. Her starring film ''Koisora'' became a massive hit, earning her numerous film awards. In 2011, she made her first lead role in a TV drama with ''Zenkai Girl,'' and since then, she has appeared in many works, including ''Legal High,'' ''The Flying Public Relations Office,'' and the social phenomenon ''Nigeru wa Haji da ga Yaku ni Tatsu.'' The film ''Code Blue: The Movie,'' which started as a drama series, topped the box office for Japanese films in 2018. That same year, the drama ''We Can''t Be Beast'' she starred in also gained attention. She is actively involved in a wide range of activities, including films, dramas, commercials, and magazines.

