update content_bodies set title = '志田未来｜Travel to 豊田市 旅の楽しみが全部かなうハイブリッドな旅【旅色Movie】', description = '愛知県のほぼ中央に位置し、“クルマのまち”として知られる豊田市。世界をリードするものづくり都市でありながら市域の約７割を森林が占め、車をちょっと走らせれば緑豊かな山里が「ようこそ」と出迎えてくれます。建物ごとアートのような美術館や博物館は都会の表情。歴史的スポットは懐かしさを感じさせるふるさとの顔。“最先端”と“懐かしさ”とがバランスよく融合した豊田市で志田未来さんがハイブリッドな旅を楽しみました。

┈┈志田未来 Profile┈┈
1993年生まれ、神奈川県出身。2006年にドラマ『14才の母』（日本テレビ系）で主演を務め、話題に。映画『誰も守ってくれない』（2009年）で日本アカデミー賞新人俳優賞を受賞。ドラマや映画を中心に数多くの作品に出演し、声優としても活躍中。近作に、『劇場版 ACMA：GAME 最後の鍵』が10月25日（金）全国公開、主演ドラマ『下山メシ』（テレビ東京系）が11月14日（木）スタート、11月28日からPrime Videoで配信する『推しの子』にも出演する。

