update content_bodies set title = 'Mirai Shida | Travel to Toyota City - A Hybrid Journey Where All Travel Pleasures Come True【Tabiiro Movie】', description = 'Located almost in the center of Aichi Prefecture, Toyota City is known as the ''City of Cars.'' While being a world-leading manufacturing city, about 70% of the area is covered by forests, and just a short drive away, lush green mountains welcome you with a ''Welcome.'' The art-like museums and galleries present an urban face, while historical spots evoke a sense of nostalgia, showcasing the hometown''s charm. In Toyota City, where ''cutting-edge'' and ''nostalgia'' are harmoniously blended, Mirai Shida enjoyed a hybrid journey.

┈┈Mirai Shida Profile┈┈
Born in 1993, from Kanagawa Prefecture. Gained attention for her leading role in the drama ''14-Year-Old Mother'' (Nippon Television) in 2006. Won the New Actor Award at the Japan Academy Prize for the film ''No One Will Protect You'' (2009). She has appeared in numerous works, mainly in dramas and films, and is also active as a voice actress. Her recent works include ''ACMA:GAME The Last Key'' which will be released nationwide on October 25 (Friday), the leading drama ''Shimoyama Meshi'' (TV Tokyo) starting on November 14 (Thursday), and she will also appear in ''Oshi no Ko'' which will be available on Prime Video from November 28.

