update content_bodies set title = 'Fantastique Toba', description = '「Fantastique Toba」
 
 
Venez découvrir la ville de Toba. 
Ici les femmes et les hommes ont construit un lien unique avec la mer, à l’image des plongeuses ama et leur tradition ancestrale de pêche durable. 
Plus qu’une simple escale, c''est une invitation à repenser notre relation à la nature.
 
 
Come and discover the city of Toba.
Having traditions such as the Ama divers and their unique way of sustainable fishing, the women and men of Toba have built a special bond with the sea.
More than a simple step along the way, it''s a good chance to let us rethink the relationship between nature and men.
 
 
鳥羽へようこそ。
ここでは、海女さんや先祖代々の伝統である持続可能な漁業のように女性も男性も海と独自の絆を築いています。
単なる立ち寄りスポットではなく、自然と私たちの関係を見直すきっかけになるかもしれません。
 
 
Toba Sea-Folk Museum 0:56
Toba City Fisheries Research Institute 1:51
Oyster Farm 3:01
Mikimoto Pearl Island 4:29
Ama Hut Experience (Hachiman Kamado) 5:43
Tōshijima island 6:49
Ama hut 8:40
 
 
Facebook : https://www.facebook.com/profile.php?id=100078342158372
 
Instagram : https://www.instagram.com/fantastique_toba/
 
Want to know more about what you can do in Toba ? Check out our website in English Dive into Toba : http://toba.gr.jp/en/' where id = 'tWzA_YDEdSok5JK5FmAKq';